/* v2.8 support inventory and reward data. Existing cards / combat stats are untouched. */
const BATTLE_REWARDS28={solo:{points:100,chance:.20},duo:{points:150,chance:.30},trio:{points:200,chance:.40}};
function supportIcon28(kind){const paths={stop:'<circle cx="12" cy="13" r="8"/><path d="M9 2h6M12 2v3M12 8v5l3 2M18 5l2-2"/>',wall:'<path d="M12 2 21 6v6c0 5-9 10-9 10S3 17 3 12V6Z"/><path d="m8 12 3 3 5-6"/>',ticket:'<path d="M3 5h18v5a2 2 0 0 0 0 4v5H3v-5a2 2 0 0 0 0-4Z"/><path d="M15 7v2m0 2v2m0 2v2"/>'};return `<svg class="support-icon28" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[kind]}</svg>`;}
const ITEMS28={heart:{name:'ハート＋1チケット',short:'ハート＋1',icon:'♥',cost:3,description:'開始時のライフと上限を＋1。このプレイだけ。'},stop:{name:'時止め5秒チケット',short:'時止め5秒',icon:supportIcon28('stop'),cost:3,description:'好きな時に発動。敵の接近を5秒止め、入力は続けられます。'},wall:{name:'防壁チケット',short:'防壁',icon:supportIcon28('wall'),cost:4,description:'敵が防衛線に到達したとき、ダメージを1回だけ防ぎます。'}};
function extendSupport28(out,source={}){const old=source.support28||{},acquired={},spent={},items={};for(const id of Object.keys(ITEMS28)){spent[id]=safe24Int(old.spent?.[id]);acquired[id]=Math.max(safe24Int(old.acquired?.[id]),safe24Int(old.items?.[id])+spent[id]);items[id]=Math.max(0,acquired[id]-spent[id]);}out.support28={...old,schema:1,items,acquired,spent,shardsSpent:safe24Int(old.shardsSpent),lastRun:old.lastRun&&typeof old.lastRun==='object'?{era:GAME_DATA.eras.some(e=>e.id===old.lastRun.era)?old.lastRun.era:null,selected:ITEMS28[old.lastRun.selected]?old.lastRun.selected:null,used:ITEMS28[old.lastRun.used]?old.lastRun.used:null}:null};return out;}
function grantTicket28(state,id){if(!ITEMS28[id])return false;state.support28.acquired[id]++;state.support28.items[id]++;return true;}
function consumeTicket28(state,id){if(!ITEMS28[id]||state.support28.items[id]<=0)return false;state.support28.items[id]--;state.support28.spent[id]++;return true;}
function exchangeTicket28(state,id){const item=ITEMS28[id];if(!item||state.awakening26.fragments<item.cost)return false;state.awakening26.fragments-=item.cost;state.support28.shardsSpent+=item.cost;grantTicket28(state,id);return true;}
function rollTicket28(mode,rng=Math.random){const r=BATTLE_REWARDS28[mode];if(!r||rng()>=r.chance)return null;return Object.keys(ITEMS28)[Math.min(2,Math.floor(rng()*3))];}
// Preserve the earned-fragment ledger and subtract spending after merging snapshots.
const mergeAwakeningBefore28=mergeAwakening26;
mergeAwakening26=function(current,incoming){extendSupport28(current,current);extendSupport28(incoming,incoming);const a=current.support28,b=incoming.support28,spentFragments=Math.max(a.shardsSpent,b.shardsSpent);const ca={...current,awakening26:{...current.awakening26,fragments:current.awakening26.fragments+a.shardsSpent}},ib={...incoming,awakening26:{...incoming.awakening26,fragments:incoming.awakening26.fragments+b.shardsSpent}};const merged=mergeAwakeningBefore28(ca,ib);merged.awakening26.fragments=Math.max(0,merged.awakening26.fragments-spentFragments);const support={...a,...b,shardsSpent:spentFragments,items:{},acquired:{},spent:{},lastRun:b.lastRun||a.lastRun};for(const id of Object.keys(ITEMS28)){support.acquired[id]=Math.max(a.acquired[id],b.acquired[id]);support.spent[id]=Math.max(a.spent[id],b.spent[id]);support.items[id]=Math.max(0,support.acquired[id]-support.spent[id]);}merged.support28=support;return merged;};
